UPDATE content SET overview_uk = v.overview_uk, has_uk_translation = true FROM (VALUES
  (104, 'На піку Першої світової війни двоє молодих британських солдатів мають перетнути ворожу територію та доставити повідомлення, яке зупинить смертельну атаку на сотні військових.'),
  (859, 'Слідкуйте за пригодами групи молодих мультиплікаційних персонажів, які навчаються в Акме Луноверситеті, щоб стати наступним поколінням героїв серіалу Луні Тюнз.'),
  (1747, 'Вирушивши на місію зробити Різдво незабутнім для Квілла, Вартові Галактики вирушають на Землю в пошуках ідеального подарунка.'),
  (2345, 'Мисливець за трюфелями, який живе на самоті в лісах Орегону, змушений вирушити до Портленда, щоб знайти таємничу особу, яка викрала його улюблену свиню-шукачку.'),
  (2465, 'Одного мирного дня на Землі двоє залишків армії Фрізи на ім''я Сорбет і Тагома прибувають у пошуках Кульок Дракона з метою воскресити Фрізу. Їм це вдається, і Фріза вирушає мстити Саянам.'),
  (2686, 'Майлз Монро, кларнетист і власник магазину здорового харчування, пробуджується після кріосну через 200 років у майбутньому, щоб допомогти повстанцям боротися з тиранічним урядовим режимом.'),
  (2951, 'Люблячий батько знаходить костюм клоуна для дня народження свого сина, але незабаром усвідомлює, що костюм є частиною зловісного прокляття, яке перетворює того, хто його вдягне, на вбивцю.'),
  (3017, 'Молодята Дженніфер зазнає жорстокого нападу на темній зупинці. Оговтуючись від травм, вона не може згадати нічого зі свого минулого, включно з тією подією. Її чоловік Рассел просто вдячний, що вона жива, і прагне забрати її додому. Поки він знайомить її заново з їхнім відлюдним гірським маєтком, детектив Пейдж переслідує нападника Дженніфер — його власна донька зникла і так і не була знайдена. Та сама доля чекає на Дженніфер, якщо хтось не зрозуміє, що її люблячий опікун насправді є її викрадачем.'),
  (3026, 'Сім''я ховається в протирадіаційному бункері, щоб уникнути небезпечного спалаху епідемії.'),
  (3065, 'Джордж Латц, його дружина Кеті та їхні троє дітей щойно переїхали в чудовий і неймовірно дешевий вікторіанський особняк у тихому прибережному містечку Амітівілль на Лонг-Айленді. Проте їхній будинок мрії приховує жахливе минуле, і незабаром кожен член родини Латц починає страждати від дедалі дивніших і жорстокіших видінь та імпульсів.'),
  (3792, 'Двоє дітей опиняються в центрі смертельної гри в кота й мишку після того, як викрадають патрульний автомобіль шерифа заради розваги.'),
  (4267, 'Маленька лампа знаходить м''ячик для гри, і все чудово, поки м''ячик не лопає. Щойно старший Люксо думає, що його малюк заспокоїться, Люксо-молодший знаходить м''яч удесятеро більший.'),
  (4300, 'Минуло тринадцять років відтоді, як Андроїди розпочали свій нищівний похід, і Сон Гохан залишається єдиним, хто чинить опір. Він бере сина Бульми, Транкса, собі в учні й навіть віддає власне життя, щоб врятувати його. Тепер Транкс має знайти спосіб змінити це апокаліптичне майбутнє.'),
  (4304, 'На високогірному плато живе ягня з вовною такого дивовижного блиску, що він пускається у запальний танок. Але настає день, коли він втрачає своє розкішне руно, а разом із ним — і гордість. Лише мудрий джекелоп — рогатий кролик — здатен навчити засмученого баранця, що з вовною чи без неї, саме те, що всередині, допоможе йому оговтатися від життєвих негараздів.'),
  (4315, 'Севасі та Дораемон потрапляють назад у минуле й зустрічають Нобіту. Дораемон має подбати про Нобіту, інакше він не зможе повернутися в сьогодення.'),
  (4363, 'Таємнича група ніндзя здійснює раптову атаку на Конохагакуре, завдаючи серйозних збитків. Кошмар нової Світової Війни Шінобі може стати реальністю. Саске, який досі залишається зниклим ніном Конохи й намагається вбити свого брата Ітачі, вдруге з''являється перед Наруто в невідомому місці, щоб запобігти цьому.')
) AS v(id, overview_uk) WHERE content.id = v.id;
